<span class="line"><span style="color:#C678DD">def</span><span style="color:#61AFEF"> ReadFileToArray</span><span style="color:#ABB2BF">(</span><span style="color:#D19A66;font-style:italic">FILENAME</span><span style="color:#ABB2BF">):</span></span>
